--
-- Table structure for table `pm_custom_field_definitions`
--

CREATE TABLE `pm_custom_field_definitions` (
  `id` int(11) NOT NULL,
  `practice_id` int(11) NOT NULL,
  `field_name` varchar(100) NOT NULL,
  `field_label` varchar(150) NOT NULL,
  `field_type` varchar(50) NOT NULL DEFAULT 'text',
  `target_entity` varchar(50) NOT NULL DEFAULT 'client',
  `options_json` text DEFAULT NULL,
  `is_required` tinyint(1) DEFAULT 0,
  `sort_order` int(11) DEFAULT 0,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- --------------------------------------------------------

--
-- Table structure for table `pm_custom_field_values`
--

CREATE TABLE `pm_custom_field_values` (
  `id` int(11) NOT NULL,
  `definition_id` int(11) NOT NULL,
  `entity_id` int(11) NOT NULL,
  `value_text` text DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

